package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// latex: generate a .tex resume from the bank using the CV's own Preamble.tex
// macros, so Overleaf / latexmk builds keep working. Generated files live in
// latex_out_dir (career/CurriculumVitae/generated) and are never edited by
// hand. Build from the CV folder so \input{core/Preamble.tex} and Claims.tex resolve:
//   cd <code_root>/<cv_dir> && latexmk -pdf -outdir=output/generated generated/<name>.tex

func buildLatex(c *Composed, selPath string) string {
	bf := c.boldFigures()
	t := func(s string) string { return mdToTeX(s, bf) }
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("%% GENERATED by rkb from %s — do not edit; edit the bank and regenerate.\n", filepath.Base(selPath))
	w("%% Target: %s\n", c.Meta.Target)
	w("\\input{core/Preamble.tex}\n\\resumetrue\n\\clubpenalty=10000 \\widowpenalty=10000 \\displaywidowpenalty=10000\n\n\\begin{document}\n\n")
	if c.Meta.Origin != "" || true {
		w("\\input{core/Header.tex}\n\n")
	}
	for _, s := range c.Sections {
		if s.Lead == "" && len(s.Bullets) == 0 && len(s.Lines) == 0 && len(s.Entries) == 0 {
			continue
		}
		w("\\section{%s}\n", escPlain(s.Title))
		if s.Lead != "" {
			w("\\textit{%s}\\\\[2pt]\n", t(s.Lead))
		}
		switch s.Kind {
		case "bullets":
			if len(s.Bullets) > 0 {
				w("\\resumeItemListStart\n")
				for _, x := range s.Bullets {
					w("    \\resumeItem{%s}\n", t(x.Text))
				}
				w("\\resumeItemListEnd\n\\vspace{-6pt}\n\n")
			}
		case "lines":
			if s.Bulleted {
				if len(s.Lines) > 0 {
					w("\\resumeItemListStart\n")
					for _, l := range s.Lines {
						w("    \\resumeItem{%s}\n", t(l.Text))
					}
					w("\\resumeItemListEnd\n\n")
				}
				continue
			}
			w("\\begin{tabularx}{\\textwidth}{@{}p{0.21\\textwidth}>{\\RaggedRight\\arraybackslash}X@{}}\n")
			for _, l := range s.Lines {
				if l.Label != "" {
					w("\\textbf{%s}: & %s \\\\\n", t(l.Label), t(l.Text))
				} else {
					w("\\multicolumn{2}{@{}l@{}}{%s} \\\\\n", t(l.Text))
				}
			}
			w("\\end{tabularx}\n\\vspace{-4pt}\n\n")
		default:
			w("\\resumeSubHeadingListStart\n")
			for _, e := range s.Entries {
				full := e.Title
				if len(e.Members) > 0 {
					full += ": " + strings.Join(e.Members, ", ")
				}
				switch {
				case e.Layout == "stacked":
					w("    \\resumeSubheading{%s}{%s}{%s}{}\n", t(full), t(e.Dates), t(e.Org))
				case e.Dates != "":
					w("    \\resumeProfessionalExperience{%s}{%s}{%s}\n", t(full), t(e.Org), t(e.Dates))
				default:
					w("    \\resumeAcademicProject{%s}{%s}\n", t(full), t(e.Stack))
				}
				if e.Lead != "" {
					w("    \\item[] \\textit{%s}\\vspace{-2pt}\n", t(e.Lead))
				}
				if len(e.Bullets) > 0 {
					w("    \\resumeItemListStart\n")
					for _, x := range e.Bullets {
						w("        \\resumeItem{%s}\n", t(x.Text))
					}
					w("    \\resumeItemListEnd\n")
				}
				w("\n")
			}
			w("\\resumeSubHeadingListEnd\n\\vspace{-8pt}\n\n")
		}
	}
	w("\\end{document}\n")
	return b.String()
}

func cmdLatex(a *args) {
	sel := a.need(0, "resume")
	c := loadResume(sel)
	dir := a.get("out-dir", inRoot(cfg.LatexOutDir))
	out := filepath.Join(dir, c.basename(sel)+".tex")
	writeFile(out, buildLatex(c, sel))
	fmt.Printf("wrote %s\n", out)
	if a.bools["compile"] {
		cv := inRoot(cfg.CVDir)
		rel, _ := filepath.Rel(cv, out)
		outDir := filepath.Join(cv, "output", "generated")
		if err := os.MkdirAll(outDir, 0o755); err != nil {
			die("latex: %v", err)
		}
		for i := 0; i < 2; i++ {
			cmd := exec.Command("pdflatex", "-interaction=nonstopmode", "-halt-on-error", "-output-directory="+outDir, rel)
			cmd.Dir = cv
			o, err := cmd.CombinedOutput()
			if err != nil {
				lines := strings.Split(string(o), "\n")
				die("pdflatex failed:\n%s", strings.Join(lines[max(0, len(lines)-25):], "\n"))
			}
		}
		pdf := filepath.Join(outDir, strings.TrimSuffix(filepath.Base(out), ".tex")+".pdf")
		targetP := expectedPages(c, sel)
		fills, bullets, overMax, threeLine, probs := verifyPDF(pdf, c.paper(), targetP)
		var pf []string
		for i, f := range fills {
			pf = append(pf, fmt.Sprintf("p%d %.1f%%", i+1, 100*f))
		}
		fmt.Printf("compiled %s (%d/%d pages; fill: %s; bullets: %d total, %d three-line [2 preferred], %d >3-line)\n",
			pdf, len(fills), targetP, strings.Join(pf, ", "), len(bullets), len(threeLine), len(overMax))
		for _, p := range probs {
			fmt.Printf("  LAYOUT ERROR: %s\n", p)
		}
	}
}
